  if (key === "SUPABASE_URL") {
    return configSheetLookup("NEXT_PUBLIC_SUPABASE_URL") || fallback || "";
  }
  if (key === "SUPABASE_SERVICE_KEY") {
    return configSheetLookup("SUPABASE_SERVICE_ROLE_KEY") || fallback || "";
  }
